// Same check as book_appointment: x-retell-signature = "v=<ms timestamp>,d=<hex>",
// hex = HMAC-SHA256(raw_body + timestamp) keyed with the webhook-badge Retell API key (n8n Variable RETELL_API_KEY).
const crypto = require('crypto');
const MAX_AGE_MS = 5 * 60 * 1000;

const item = $input.first();
const headers = item.json.headers ?? {};
const header = String(headers['x-retell-signature'] ?? '');
const key = $vars.RETELL_API_KEY ?? '';

let raw = '';
if (item.binary?.data) {
  raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
}
let body = item.json.body;
if ((!body || Object.keys(body).length === 0) && raw) {
  try { body = JSON.parse(raw); } catch (e) { body = {}; }
}

let ok = false;
const match = /^v=(\d+),d=([0-9a-f]+)$/i.exec(header);
if (key && raw && match && Math.abs(Date.now() - Number(match[1])) <= MAX_AGE_MS) {
  const expected = crypto.createHmac('sha256', key).update(raw + match[1]).digest('hex');
  const a = Buffer.from(expected, 'hex');
  const b = Buffer.from(match[2], 'hex');
  ok = a.length === b.length && crypto.timingSafeEqual(a, b);
}

return [{ json: { signature_ok: ok, event: body?.event ?? '', call: body?.call ?? {} } }];

// One message per call (CLAUDE.md §5.3). Retell retries webhooks, so each call_id is sent once.
const ZONE = 'America/New_York';
const call = $input.first().json.call ?? {};
const callId = String(call.call_id ?? '');

const memory = $getWorkflowStaticData('global');
memory.sentCallIds = memory.sentCallIds ?? [];
if (callId && memory.sentCallIds.includes(callId)) return [];
if (callId) memory.sentCallIds = [...memory.sentCallIds, callId].slice(-500);

const d = call.call_analysis?.custom_analysis_data ?? {};
const esc = s => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const val = x => (x === undefined || x === null || String(x).trim() === '') ? '—' : esc(String(x).trim());
const yes = x => x === true || String(x).toLowerCase() === 'true';

const type = String(d.call_type ?? 'other').toLowerCase();
const titles = {
  standard: '🛠 <b>Standard repair call</b>',
  warranty: '🛡 <b>Warranty repair call</b>',
  warranty_company_rep: '🏢 <b>Warranty company rep</b>',
  spam: '🚫 <b>Spam / irrelevant</b>',
  other: '📞 <b>Other call</b>'
};
const startedAt = call.start_timestamp
  ? DateTime.fromMillis(Number(call.start_timestamp)).setZone(ZONE).toFormat('ccc LLL d, h:mm a') + ' ET'
  : '—';
const durationMs = call.duration_ms ?? (call.end_timestamp && call.start_timestamp ? call.end_timestamp - call.start_timestamp : null);
const duration = durationMs != null ? Math.floor(durationMs / 60000) + 'm ' + Math.round((durationMs % 60000) / 1000) + 's' : '—';
const summary = d.summary ?? call.call_analysis?.call_summary;

const lines = [titles[type] ?? titles.other, startedAt + ' · ' + duration + ' · from ' + val(call.from_number), ''];

if (type === 'standard' || type === 'warranty') {
  const warranty = type === 'warranty' || yes(d.is_warranty);
  const fee = warranty ? 'Warranty, no fee' : (yes(d.fee_accepted) ? '$99 accepted' : '$99 not accepted');
  const status = String(d.booking_status ?? '').toLowerCase();
  const booking = status === 'booked' ? '✅ Booked: ' + val(d.booking_time)
    : status === 'declined_fee' ? '❌ Not booked: caller declined the $99 fee'
    : '❌ Not booked';
  lines.push(
    'Name: ' + val(d.caller_name),
    'Phone: ' + val(d.callback_number || call.from_number),
    'Address: ' + val(d.service_address),
    'Appliance: ' + val(d.appliance_type),
    'Brand: ' + val(d.brand),
    'Issue: ' + val(d.issue_description),
    'Fee: ' + fee,
    booking
  );
} else if (type === 'warranty_company_rep') {
  lines.push(
    'Rep: ' + val(d.caller_name),
    'Company: ' + val(d.rep_company),
    'Callback: ' + val(d.callback_number || call.from_number),
    'Job: ' + val(d.rep_job_description),
    '📞 Callback promised'
  );
} else {
  lines.push('Caller: ' + val(call.from_number));
}
lines.push('', 'Summary: ' + val(summary));

return [{ json: { text: lines.join('\n') } }];
